/**
 * Guards for ids a change points at: each must be usable from the workspace
 * the change is made in. Another workspace's row is a tenant-scope violation;
 * anything absent, archived or otherwise unusable is not found.
 */
import { TenantScopeError } from "@/lib/tenant";
import { isArchived } from "@/lib/soft-delete";
import * as commentRepo from "@/server/repositories/comment-repository";
import * as issueRepo from "@/server/repositories/issue-repository";
import * as labelRepo from "@/server/repositories/label-repository";
import * as memberRepo from "@/server/repositories/member-repository";
import { NotFoundError } from "./_support";
import type {
  CommentId,
  IssueId,
  LabelId,
  OrgId,
  ProjectId,
  UserId,
} from "@/types/common";

export async function assertCurrentMember(
  orgId: OrgId,
  userId: UserId | null | undefined,
): Promise<void> {
  if (userId === null || userId === undefined) return;
  const member = await memberRepo.findMember(orgId, userId);
  if (!member) throw new NotFoundError("Member", userId);
}

export async function assertLabelsInOrg(
  orgId: OrgId,
  labelIds: readonly LabelId[] | undefined,
): Promise<void> {
  if (!labelIds || labelIds.length === 0) return;
  const owners = await labelRepo.findLabelOrgs(labelIds);
  for (const id of labelIds) {
    const owner = owners[id];
    if (owner === undefined) throw new NotFoundError("Label", id);
    if (owner !== orgId) throw new TenantScopeError(orgId, owner);
  }
}

export async function assertLiveParentIssue(
  orgId: OrgId,
  projectId: ProjectId,
  parentId: IssueId | null | undefined,
): Promise<void> {
  if (parentId === null || parentId === undefined) return;
  const parent = await issueRepo.findIssueInAnyOrg(parentId);
  if (!parent) throw new NotFoundError("Issue", parentId);
  if (parent.orgId !== orgId) throw new TenantScopeError(orgId, parent.orgId);
  if (isArchived(parent) || parent.projectId !== projectId) {
    throw new NotFoundError("Issue", parentId);
  }
}

export async function assertReplyTarget(
  orgId: OrgId,
  issueId: IssueId,
  parentId: CommentId | null | undefined,
): Promise<void> {
  if (parentId === null || parentId === undefined) return;
  const parent = await commentRepo.findCommentInAnyOrg(parentId);
  if (!parent) throw new NotFoundError("Comment", parentId);
  if (parent.orgId !== orgId) throw new TenantScopeError(orgId, parent.orgId);
  if (
    isArchived(parent) ||
    parent.issueId !== issueId ||
    parent.parentId !== null
  ) {
    throw new NotFoundError("Comment", parentId);
  }
}
